<?php
if (!defined('ABSPATH')) { exit; }
/** Ventes, clients, dettes et dépenses. */
final class FKC_Sales_API {
 private static function t($n){global $wpdb;return in_array($n,array('users','tenants','branches','members','permissions','branch_access','invitations','audit_logs','sessions'),true)?'bta_'.$n:$wpdb->prefix.'bta_'.$n;}
 private static function err($c,$m,$s=400){return new WP_Error($c,$m,array('status'=>$s));}
 private static function auth($r,$tenant,$perm){$h=$r->get_header('authorization');if(!$h&&isset($_SERVER['HTTP_AUTHORIZATION']))$h=wp_unslash($_SERVER['HTTP_AUTHORIZATION']);if(!is_string($h)||!preg_match('/^Bearer\s+([a-fA-F0-9]{64})$/',$h,$m))return self::err('bta_unauthenticated','Connexion requise.',401);global $wpdb;$s=$wpdb->get_row($wpdb->prepare('SELECT s.user_id,u.status FROM '.self::t('sessions').' s JOIN '.self::t('users').' u ON u.id=s.user_id WHERE s.token_hash=%s AND s.expires_at>%s LIMIT 1',hash('sha256',$m[1]),gmdate('Y-m-d H:i:s')),ARRAY_A);if(!$s||$s['status']!=='ACTIVE')return self::err('bta_unauthenticated','Session invalide ou expirée.',401);$mem=$wpdb->get_row($wpdb->prepare("SELECT role FROM ".self::t('members')." WHERE tenant_id=%d AND user_id=%d AND status='ACTIVE' LIMIT 1",$tenant,$s['user_id']),ARRAY_A);if(!$mem)return self::err('bta_forbidden','Accès refusé.',403);$map=array('OWNER'=>array('sales.read','sales.create','sales.cancel','customers.read','customers.manage','debts.read','debts.pay','expenses.read','expenses.create'),'ADMIN'=>array('sales.read','sales.create','sales.cancel','customers.read','customers.manage','debts.read','debts.pay','expenses.read','expenses.create'),'MANAGER'=>array('sales.read','sales.create','sales.cancel','customers.read','customers.manage','debts.read','debts.pay','expenses.read','expenses.create'),'CASHIER'=>array('sales.read','sales.create','customers.read','debts.read','debts.pay'));if(!in_array($perm,$map[$mem['role']]??array(),true))return self::err('bta_forbidden','Permission insuffisante.',403);return array('user_id'=>(int)$s['user_id']);}
 private static function cash_in_out($tenant,$branch,$user,$currency,$amount,$type,$reference_type,$reference_id,$description){
  global $wpdb;
  $session=$wpdb->get_row($wpdb->prepare("SELECT id FROM ".self::t('cash_sessions')." WHERE tenant_id=%d AND branch_id=%d AND user_id=%d AND currency=%s AND status='OPEN' ORDER BY id DESC LIMIT 1 FOR UPDATE",$tenant,$branch,$user,$currency),ARRAY_A);
  if(!$session)return self::err('bta_open_cash_required','Une caisse ouverte dans la devise concernée est nécessaire pour cette opération en espèces.',409);
  $ok=$wpdb->insert(self::t('cash_movements'),array('tenant_id'=>$tenant,'cash_session_id'=>$session['id'],'movement_type'=>$type,'amount'=>$amount,'currency'=>$currency,'description'=>$description,'reference_type'=>$reference_type,'reference_id'=>$reference_id,'created_by'=>$user,'created_at'=>gmdate('Y-m-d H:i:s')));
  if(!$ok)return self::err('bta_cash_record_failed','Mouvement de caisse non enregistré.',500);
  return true;
 }
 private static function page($r,$sql,$args,$key) {
  global $wpdb;$page=max(1,(int)$r->get_param('page'));$limit=min(100,max(1,(int)($r->get_param('per_page')?:100)));
  $total=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM ('.$sql.') bta_page_count',$args));
  $rows=$wpdb->get_results($wpdb->prepare($sql.' LIMIT %d OFFSET %d',array_merge($args,array($limit,($page-1)*$limit))),ARRAY_A);
  return array('success'=>true,$key=>$rows,'pagination'=>array('page'=>$page,'per_page'=>$limit,'total'=>$total,'pages'=>(int)ceil($total/$limit)));
 }
 public static function boot(){add_action('rest_api_init',array(__CLASS__,'routes'));}
 public static function routes(){register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/customers',array(array('methods'=>'GET','callback'=>array(__CLASS__,'customers'),'permission_callback'=>'__return_true'),array('methods'=>'POST','callback'=>array(__CLASS__,'customer_create'),'permission_callback'=>'__return_true')));register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/sales',array(array('methods'=>'GET','callback'=>array(__CLASS__,'sales'),'permission_callback'=>'__return_true'),array('methods'=>'POST','callback'=>array(__CLASS__,'sale_create'),'permission_callback'=>'__return_true')));register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/sales/(?P<sale_id>\d+)/cancel',array('methods'=>'POST','callback'=>array(__CLASS__,'sale_cancel'),'permission_callback'=>'__return_true'));register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/debts',array('methods'=>'GET','callback'=>array(__CLASS__,'debts'),'permission_callback'=>'__return_true'));register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/debts/(?P<debt_id>\d+)/payments',array('methods'=>'POST','callback'=>array(__CLASS__,'debt_payment'),'permission_callback'=>'__return_true'));register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/expenses',array(array('methods'=>'GET','callback'=>array(__CLASS__,'expenses'),'permission_callback'=>'__return_true'),array('methods'=>'POST','callback'=>array(__CLASS__,'expense_create'),'permission_callback'=>'__return_true')));}
 public static function customers($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'customers.read');if(is_wp_error($a))return $a;global $wpdb;$q=sanitize_text_field((string)$r->get_param('q'));$sql='SELECT id,name,phone,email,address,notes,credit_limit,created_at FROM '.self::t('customers').' WHERE tenant_id=%d';$args=array($t);if($q!==''){$like='%'.$wpdb->esc_like($q).'%';$sql.=' AND (name LIKE %s OR phone LIKE %s OR email LIKE %s)';array_push($args,$like,$like,$like);}$sql.=' ORDER BY id DESC';return self::page($r,$sql,$args,'customers');}
 public static function customer_create($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'customers.manage');if(is_wp_error($a))return $a;$name=sanitize_text_field((string)$r->get_param('name'));if(strlen($name)<2)return self::err('bta_invalid_customer','Nom du client obligatoire.');global $wpdb;$now=gmdate('Y-m-d H:i:s');$ok=$wpdb->insert(self::t('customers'),array('tenant_id'=>$t,'name'=>$name,'phone'=>sanitize_text_field((string)$r->get_param('phone')),'email'=>sanitize_email((string)$r->get_param('email')),'address'=>sanitize_textarea_field((string)$r->get_param('address')),'notes'=>sanitize_textarea_field((string)$r->get_param('notes')),'credit_limit'=>max(0,(float)$r->get_param('credit_limit')),'created_at'=>$now,'updated_at'=>$now));if(!$ok)return self::err('bta_customer_failed',$wpdb->last_error?:'Création impossible.',500);return new WP_REST_Response(array('success'=>true,'customer'=>array('id'=>(int)$wpdb->insert_id,'name'=>$name,'credit_limit'=>max(0,(float)$r->get_param('credit_limit')))),201);}
 public static function sales($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'sales.read');if(is_wp_error($a))return $a;global $wpdb;$page=max(1,(int)$r->get_param('page'));$lim=min(100,max(1,(int)($r->get_param('per_page')?:25)));$b=absint($r->get_param('branch_id'));$sql='SELECT id,branch_id,customer_id,reference,status,currency,subtotal,discount,total,paid,balance,created_at FROM '.self::t('sales').' WHERE tenant_id=%d';$args=array($t);if($b){$sql.=' AND branch_id=%d';$args[]=$b;}$sql.=' ORDER BY id DESC LIMIT %d OFFSET %d';$args[]=$lim;$args[]=($page-1)*$lim;$rows=$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A);$count_sql='SELECT COUNT(*) FROM '.self::t('sales').' WHERE tenant_id=%d';$count_args=array($t);if($b){$count_sql.=' AND branch_id=%d';$count_args[]=$b;}$total=(int)$wpdb->get_var($wpdb->prepare($count_sql,$count_args));return array('success'=>true,'sales'=>$rows,'pagination'=>array('page'=>$page,'per_page'=>$lim,'total'=>$total,'pages'=>(int)ceil($total/$lim)));}
 public static function sale_create($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'sales.create');if(is_wp_error($a))return $a;$branch=absint($r->get_param('branch_id'));$customer=absint($r->get_param('customer_id'));$ref=sanitize_text_field((string)$r->get_param('reference'));$currency=strtoupper((string)($r->get_param('currency')?:'USD'));$rate=(float)($r->get_param('exchange_rate')?:1);$items=$r->get_param('items');if(!$branch||strlen($ref)<2||!in_array($currency,array('USD','CDF'),true)||$rate<=0||!is_array($items)||!count($items))return self::err('bta_invalid_sale','Établissement, référence, devise, taux et articles requis.');global $wpdb;if(!$wpdb->get_var($wpdb->prepare("SELECT id FROM ".self::t('branches')." WHERE id=%d AND tenant_id=%d AND status='ACTIVE'",$branch,$t)))return self::err('bta_invalid_branch','Établissement introuvable.',404);if($customer&&!$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::t('customers').' WHERE id=%d AND tenant_id=%d',$customer,$t)))return self::err('bta_invalid_customer','Client introuvable.',404);$clean=array();$subtotal=0;foreach($items as $it){$pid=absint($it['product_id']??0);$qty=(float)($it['quantity']??0);$price=(float)($it['unit_price']??-1);if(!$pid||$qty<=0||$price<0)return self::err('bta_invalid_sale_item','Article, quantité ou prix invalide.');$prod=$wpdb->get_row($wpdb->prepare("SELECT id,sale_price FROM ".self::t('products')." WHERE id=%d AND tenant_id=%d AND status='ACTIVE'",$pid,$t),ARRAY_A);if(!$prod)return self::err('bta_invalid_sale_item','Produit introuvable.',404);$line=$qty*$price;$subtotal+=$line;$clean[]=array($pid,$qty,$price,$line);}$discount=max(0,(float)$r->get_param('discount'));if($discount>$subtotal)return self::err('bta_invalid_discount','Remise supérieure au sous-total.');$total=$subtotal-$discount;$paid=max(0,(float)$r->get_param('paid'));if($paid>$total)return self::err('bta_invalid_payment','Paiement supérieur au total.');$now=gmdate('Y-m-d H:i:s');$wpdb->query('START TRANSACTION');foreach($clean as $it){$stock=$wpdb->get_row($wpdb->prepare('SELECT id,quantity FROM '.self::t('stock').' WHERE tenant_id=%d AND branch_id=%d AND product_id=%d FOR UPDATE',$t,$branch,$it[0]),ARRAY_A);if(!$stock||(float)$stock['quantity']<$it[1]){$wpdb->query('ROLLBACK');return self::err('bta_insufficient_stock','Stock insuffisant pour le produit '.$it[0].'.',409);}}$ok=$wpdb->insert(self::t('sales'),array('tenant_id'=>$t,'branch_id'=>$branch,'customer_id'=>$customer?:null,'reference'=>$ref,'status'=>'COMPLETED','currency'=>$currency,'exchange_rate'=>$rate,'subtotal'=>$subtotal,'discount'=>$discount,'total'=>$total,'paid'=>$paid,'balance'=>$total-$paid,'notes'=>sanitize_textarea_field((string)$r->get_param('notes')),'created_by'=>$a['user_id'],'created_at'=>$now));if(!$ok){$wpdb->query('ROLLBACK');return self::err('bta_sale_failed',$wpdb->last_error?:'Vente impossible.',409);}$id=(int)$wpdb->insert_id;foreach($clean as $it){$prod=$wpdb->get_row($wpdb->prepare('SELECT purchase_price FROM '.self::t('products').' WHERE id=%d AND tenant_id=%d',$it[0],$t),ARRAY_A);$wpdb->insert(self::t('sale_items'),array('tenant_id'=>$t,'sale_id'=>$id,'product_id'=>$it[0],'quantity'=>$it[1],'unit_price'=>$it[2],'unit_cost'=>(float)($prod['purchase_price']??0),'line_total'=>$it[3]));$wpdb->query($wpdb->prepare('UPDATE '.self::t('stock').' SET quantity=quantity-%f,updated_at=%s WHERE tenant_id=%d AND branch_id=%d AND product_id=%d',$it[1],$now,$t,$branch,$it[0]));$wpdb->insert(self::t('stock_movements'),array('tenant_id'=>$t,'branch_id'=>$branch,'product_id'=>$it[0],'movement_type'=>'SALE','quantity'=>-$it[1],'reference_type'=>'sale','reference_id'=>$id,'notes'=>'Vente '.$ref,'created_by'=>$a['user_id'],'created_at'=>$now));}if($paid>0){$pay_method=strtoupper(sanitize_key((string)($r->get_param('payment_method')?:'CASH')));$ok=$wpdb->insert(self::t('payments'),array('tenant_id'=>$t,'branch_id'=>$branch,'entity_type'=>'SALE','entity_id'=>$id,'payment_type'=>'CUSTOMER_PAYMENT','amount'=>$paid,'currency'=>$currency,'exchange_rate'=>$rate,'method'=>$pay_method,'reference'=>sanitize_text_field((string)$r->get_param('payment_reference')),'notes'=>'Paiement vente '.$ref,'created_by'=>$a['user_id'],'created_at'=>$now));if(!$ok){$wpdb->query('ROLLBACK');return self::err('bta_payment_failed','Paiement de vente non enregistré.',500);}if($pay_method==='CASH'){$cash=self::cash_in_out($t,$branch,$a['user_id'],$currency,$paid,'SALE_IN','sale',$id,'Encaissement vente '.$ref);if(is_wp_error($cash)){$wpdb->query('ROLLBACK');return $cash;}}}$debt_id=0;if($total>$paid){if(!$customer){$wpdb->query('ROLLBACK');return self::err('bta_customer_required','Un client est obligatoire pour une vente à crédit.');}$debt_ok=$wpdb->insert(self::t('debts'),array('tenant_id'=>$t,'branch_id'=>$branch,'customer_id'=>$customer,'sale_id'=>$id,'original_amount'=>$total,'paid_amount'=>$paid,'balance'=>$total-$paid,'currency'=>$currency,'status'=>'OPEN','created_at'=>$now,'updated_at'=>$now));if(!$debt_ok){$wpdb->query('ROLLBACK');return self::err('bta_debt_create_failed','Dette client non enregistrée.',500);}$debt_id=(int)$wpdb->insert_id;}if($wpdb->last_error){$wpdb->query('ROLLBACK');return self::err('bta_sale_transaction_failed','Erreur pendant la vente.',500);}$wpdb->query('COMMIT');return new WP_REST_Response(array('success'=>true,'sale'=>array('id'=>$id,'reference'=>$ref,'subtotal'=>$subtotal,'discount'=>$discount,'total'=>$total,'paid'=>$paid,'balance'=>$total-$paid,'currency'=>$currency,'debt_id'=>$debt_id?:null,'stock_updated'=>true)),201);}

 public static function sale_cancel($r){
  $t=(int)$r['tenant_id'];$a=self::auth($r,$t,'sales.cancel');if(is_wp_error($a))return $a;
  $id=(int)$r['sale_id'];global $wpdb;$wpdb->query('START TRANSACTION');
  $sale=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::t('sales')." WHERE id=%d AND tenant_id=%d FOR UPDATE",$id,$t),ARRAY_A);
  if(!$sale){$wpdb->query('ROLLBACK');return self::err('bta_sale_not_found','Vente introuvable.',404);}
  if($sale['status']!=='COMPLETED'){$wpdb->query('ROLLBACK');return self::err('bta_sale_not_cancellable','Cette vente n’est pas dans un état annulable.',409);}
  if((float)$sale['paid']>0){$wpdb->query('ROLLBACK');return self::err('bta_refund_required','Cette vente comporte un paiement. Le remboursement doit être géré avant son annulation.',409);}
  $debt=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::t('debts')." WHERE tenant_id=%d AND sale_id=%d FOR UPDATE",$t,$id),ARRAY_A);
  if($debt && (float)$debt['paid_amount']>0){$wpdb->query('ROLLBACK');return self::err('bta_debt_payment_exists','Cette dette a déjà reçu un paiement; annulation refusée.',409);}
  $items=$wpdb->get_results($wpdb->prepare('SELECT product_id,quantity FROM '.self::t('sale_items').' WHERE tenant_id=%d AND sale_id=%d',$t,$id),ARRAY_A);
  if(!$items){$wpdb->query('ROLLBACK');return self::err('bta_sale_items_missing','Aucune ligne de vente trouvée.',409);}
  $now=gmdate('Y-m-d H:i:s');
  foreach($items as $it){
   $stock=$wpdb->get_row($wpdb->prepare('SELECT id FROM '.self::t('stock').' WHERE tenant_id=%d AND branch_id=%d AND product_id=%d FOR UPDATE',$t,$sale['branch_id'],$it['product_id']),ARRAY_A);
   if($stock){$ok=$wpdb->query($wpdb->prepare('UPDATE '.self::t('stock').' SET quantity=quantity+%f,updated_at=%s WHERE id=%d AND tenant_id=%d',$it['quantity'],$now,$stock['id'],$t));}
   else{$ok=$wpdb->insert(self::t('stock'),array('tenant_id'=>$t,'branch_id'=>$sale['branch_id'],'product_id'=>$it['product_id'],'quantity'=>$it['quantity'],'updated_at'=>$now));}
   if($ok===false){$wpdb->query('ROLLBACK');return self::err('bta_stock_restore_failed','Restauration du stock impossible.',500);}
   $ok=$wpdb->insert(self::t('stock_movements'),array('tenant_id'=>$t,'branch_id'=>$sale['branch_id'],'product_id'=>$it['product_id'],'movement_type'=>'SALE_CANCEL','quantity'=>$it['quantity'],'reference_type'=>'sale_cancel','reference_id'=>$id,'notes'=>'Annulation vente '.$sale['reference'],'created_by'=>$a['user_id'],'created_at'=>$now));
   if(!$ok){$wpdb->query('ROLLBACK');return self::err('bta_stock_log_failed','Historique du stock non enregistré.',500);}
  }
  if($debt){$ok=$wpdb->update(self::t('debts'),array('balance'=>0,'status'=>'CANCELLED','updated_at'=>$now),array('id'=>$debt['id'],'tenant_id'=>$t));if($ok===false){$wpdb->query('ROLLBACK');return self::err('bta_debt_cancel_failed','Annulation de la dette impossible.',500);}}
  $ok=$wpdb->update(self::t('sales'),array('status'=>'CANCELLED','cancelled_at'=>$now,'cancelled_by'=>$a['user_id']),array('id'=>$id,'tenant_id'=>$t,'status'=>'COMPLETED'));
  if($ok!==1){$wpdb->query('ROLLBACK');return self::err('bta_sale_cancel_failed','Annulation de la vente impossible.',500);}
  $wpdb->query('COMMIT');return array('success'=>true,'sale_id'=>$id,'status'=>'CANCELLED','stock_restored'=>true);
 }
 public static function debts($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'debts.read');if(is_wp_error($a))return $a;global $wpdb;$b=absint($r->get_param('branch_id'));$sql='SELECT d.id,d.branch_id,d.customer_id,c.name AS customer_name,d.sale_id,d.original_amount,d.paid_amount,d.balance,d.currency,d.status,d.due_at,d.created_at FROM '.self::t('debts').' d JOIN '.self::t('customers').' c ON c.id=d.customer_id WHERE d.tenant_id=%d';$args=array($t);if($b){$sql.=' AND d.branch_id=%d';$args[]=$b;}$sql.=' ORDER BY d.id DESC';return self::page($r,$sql,$args,'debts');}
 public static function debt_payment($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'debts.pay');if(is_wp_error($a))return $a;$id=(int)$r['debt_id'];$amount=(float)$r->get_param('amount');if($amount<=0)return self::err('bta_invalid_payment','Montant invalide.');global $wpdb;$tb=self::t('debts');$wpdb->query('START TRANSACTION');$d=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$tb} WHERE id=%d AND tenant_id=%d FOR UPDATE",$id,$t),ARRAY_A);if(!$d){$wpdb->query('ROLLBACK');return self::err('bta_debt_not_found','Dette introuvable.',404);}if($amount>(float)$d['balance']){$wpdb->query('ROLLBACK');return self::err('bta_payment_exceeds_balance','Paiement supérieur au solde.');}$now=gmdate('Y-m-d H:i:s');$ok=$wpdb->insert(self::t('payments'),array('tenant_id'=>$t,'branch_id'=>$d['branch_id'],'entity_type'=>'DEBT','entity_id'=>$id,'payment_type'=>'DEBT_PAYMENT','amount'=>$amount,'currency'=>$d['currency'],'exchange_rate'=>1,'method'=>sanitize_text_field((string)($r->get_param('method')?:'CASH')),'reference'=>sanitize_text_field((string)$r->get_param('reference')),'created_by'=>$a['user_id'],'created_at'=>$now));if(!$ok){$wpdb->query('ROLLBACK');return self::err('bta_payment_failed','Paiement non enregistré.',500);}$pay_method=strtoupper(sanitize_key((string)($r->get_param('method')?:'CASH')));if($pay_method==='CASH'){$cash=self::cash_in_out($t,(int)$d['branch_id'],$a['user_id'],$d['currency'],$amount,'DEBT_IN','debt',$id,'Paiement dette #'.$id);if(is_wp_error($cash)){$wpdb->query('ROLLBACK');return $cash;}}$paid=(float)$d['paid_amount']+$amount;$bal=(float)$d['balance']-$amount;$wpdb->update($tb,array('paid_amount'=>$paid,'balance'=>$bal,'status'=>$bal<=0?'PAID':'PARTIAL','updated_at'=>$now),array('id'=>$id,'tenant_id'=>$t));if($d['sale_id'])$wpdb->update(self::t('sales'),array('paid'=>$paid,'balance'=>$bal),array('id'=>$d['sale_id'],'tenant_id'=>$t));$wpdb->query('COMMIT');return array('success'=>true,'debt_id'=>$id,'paid_amount'=>$paid,'balance'=>$bal,'status'=>$bal<=0?'PAID':'PARTIAL');}
 public static function expenses($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'expenses.read');if(is_wp_error($a))return $a;global $wpdb;$b=absint($r->get_param('branch_id'));$sql='SELECT id,branch_id,category,description,amount,currency,exchange_rate,payment_method,receipt_url,created_at FROM '.self::t('expenses').' WHERE tenant_id=%d';$args=array($t);if($b){$sql.=' AND branch_id=%d';$args[]=$b;}$sql.=' ORDER BY id DESC';return self::page($r,$sql,$args,'expenses');}
 public static function expense_create($r){$t=(int)$r['tenant_id'];$a=self::auth($r,$t,'expenses.create');if(is_wp_error($a))return $a;$b=absint($r->get_param('branch_id'));$cat=sanitize_text_field((string)$r->get_param('category'));$amount=(float)$r->get_param('amount');$cur=strtoupper((string)($r->get_param('currency')?:'USD'));$rate=(float)($r->get_param('exchange_rate')?:1);$method=strtoupper(sanitize_key((string)($r->get_param('payment_method')?:'CASH')));if(!$b||strlen($cat)<2||$amount<=0||!in_array($cur,array('USD','CDF'),true)||$rate<=0||!in_array($method,array('CASH','MOBILE_MONEY','BANK','OTHER'),true))return self::err('bta_invalid_expense','Établissement, catégorie, montant, devise, taux ou mode de paiement invalide.');global $wpdb;if(!$wpdb->get_var($wpdb->prepare("SELECT id FROM ".self::t('branches')." WHERE id=%d AND tenant_id=%d AND status='ACTIVE'",$b,$t)))return self::err('bta_invalid_branch','Établissement introuvable.',404);$now=gmdate('Y-m-d H:i:s');$wpdb->query('START TRANSACTION');$ok=$wpdb->insert(self::t('expenses'),array('tenant_id'=>$t,'branch_id'=>$b,'category'=>$cat,'description'=>sanitize_textarea_field((string)$r->get_param('description')),'amount'=>$amount,'currency'=>$cur,'exchange_rate'=>$rate,'payment_method'=>$method,'receipt_url'=>esc_url_raw((string)$r->get_param('receipt_url')),'created_by'=>$a['user_id'],'created_at'=>$now));if(!$ok){$wpdb->query('ROLLBACK');return self::err('bta_expense_failed',$wpdb->last_error?:'Dépense impossible.',500);}$id=(int)$wpdb->insert_id;if($method==='CASH'){$cash=self::cash_in_out($t,$b,$a['user_id'],$cur,$amount,'EXPENSE_OUT','expense',$id,'Dépense '.$cat);if(is_wp_error($cash)){$wpdb->query('ROLLBACK');return $cash;}}$wpdb->query('COMMIT');return new WP_REST_Response(array('success'=>true,'expense_id'=>$id,'cash_recorded'=>$method==='CASH'),201);}

}
